import re
import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFD', s.lower())
    out = []
    for ch in s:
        if ch.isascii():
            if ch.isalnum():
                out.append(ch)
            else:
                out.append('-')
        # non-ASCII characters are dropped
    return re.sub(r'-+', '-', ''.join(out)).strip('-')

def slugify(s):
    s = s.lower()
    s = s.replace('õ', 'o')
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif ch in (' ', '_'):
            out.append('-')
    s = ''.join(out)
    while '--' in s:
        s = s.replace('--', '-')
    s = s.strip('-')
    return s

